89	void revcomp(std::string& seq, std::string* qual) {
90	    std::string out;
91	    out.resize(seq.size());
92	    for (size_t i = 0; i < seq.size(); ++i) {
93	        unsigned char c = (unsigned char)seq[seq.size() - 1 - i];
94	        char d = SEQTK_COMP[c];
95	        out[i] = d ? d : 'N';
96	    }
97	    seq.swap(out);
98	    if (qual) std::reverse(qual->begin(), qual->end());
99	}
