// seqtk split: split one file into multiple smaller files (round-robin).
#include "common.h"
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <unistd.h>
#include <csignal>

static void split_usage() {
    fprintf(stderr, "Usage: seqtk split [options] <prefix> <in.fa>\n");
    fprintf(stderr, "Options:\n");
    fprintf(stderr, "  -n INT    number of files [10]\n");
    fprintf(stderr, "  -l INT    line length [0]\n");
}

int cmd_split(int argc, char *argv[]) {
    int c, n = 10, line_len = 0;
    while ((c = getopt(argc, argv, "n:l:")) >= 0) {
        if (c == 'n') n = atoi(optarg);
        else if (c == 'l') line_len = atoi(optarg);
    }
    if (argc == optind) {
        split_usage();
        return 1;
    }
    const char *prefix = argv[optind];
    // The reference passes argv[optind+1] to gzopen unconditionally;
    // with only one positional argument this is NULL and it crashes.
    if (argc == optind + 1) {
        raise(SIGSEGV);
        _exit(139);
    }
    SeqFile sf(argv[optind + 1]);
    if (!sf.is_open()) {
        fprintf(stderr, "[E::stk_split] failed to open the input file/stream.\n");
        return 1;
    }
    FILE **fps = (FILE**)calloc(n > 0 ? n : 0, sizeof(FILE*));
    if (n < 0) fps = nullptr; // calloc with negative count overflows to NULL
    for (int i = 0; i < n; ++i) {
        char *fn = (char*)malloc(strlen(prefix) + 16);
        sprintf(fn, "%s.%.5d.fa", prefix, i + 1);
        fps[i] = fopen(fn, "w");
        if (fps[i] == nullptr) {
            fprintf(stderr, "ERROR: failed to create file %s\n", fn);
            return 1;
        }
        free(fn);
    }
    SeqRecord r;
    long long i = 0;
    while (sf.next(r) > 0) {
        print_record(fps[i % n], r, line_len, false);
        ++i;
    }
    for (int j = 0; j < n; ++j) fclose(fps[j]);
    free(fps);
    return 0;
}
